input[type="radio"]{
  appearance: none;
  -webkit-appearance: none;
  width: 15px;
  height: 15px;
  border: 2px solid #584675;/*mauveine*/
  border-radius: 50%;
  background-color: #e1d4fc; /*light purple*/
  cursor: pointer;
  transition: all 0.2s ease;
}

input[type="radio"]:checked {
  background-color: #7b66a8;/*mauveine*/
  border-color: #584675;/*mauveine*/
}

input[type="checkbox"]{
    appearance: none;
  -webkit-appearance: none;
  width: 15px;
  height: 15px;
  border: 2px solid #7b66a8;/*blue*/
  background-color: #e1d4fc; /*light blue*/
  cursor: pointer;
}

